import json, pathlib, collections, struct
r=pathlib.Path(r'C:\\repo\\wargame-compiler\\private\\poc\\spqr-chapter9\\transfer\\context-v1')
p=json.loads((r/'parent/first-001.json').read_text(encoding='utf-8'))
ids=[x['id'] for c in ['evidence','nodes','rules','dependencies','gaps'] for x in p[c]]
known=set(ids)
issues=[]
fields=[]
def walk(o,path=''):
 if isinstance(o,dict):
  if 'state' in o:
   for k in ['value','evidence_ids','reason','gap_ids']:
    if k not in o: fields.append({'path':path,'issue':'missing '+k})
   if o['state']=='unknown' and (o.get('value') is not None or not o.get('gap_ids')): fields.append({'path':path,'issue':'unknown lacks null value or gap'})
  for k,v in o.items():
   if k in ['evidence_ids','gap_ids','rule_ids','node_ids','dependency_ids','affected_ids'] and isinstance(v,list):
    for i in v:
     if i not in known: issues.append({'path':path+'/'+k,'reference':i})
   walk(v,path+'/'+k)
 elif isinstance(o,list):
  for i,v in enumerate(o): walk(v,path+'/'+str(i))
walk(p)
print(json.dumps({'duplicate_ids':[i for i,n in collections.Counter(ids).items() if n>1],'reference_issues':issues,'field_issues':fields},indent=2))
for f in ['context/pass-01/evidence/8.46-step-4-pdf-27.png']:
 b=(r/f).read_bytes();print('image dimensions',struct.unpack('>II',b[16:24]))
print(json.dumps(p['coverage']['observed_objects'][:3],indent=2))
print('Other gap summaries')
for g in p['gaps']:
 print(g['id'],g['reason'])
print('Original freeze')
print((r/'inputs/v1/freeze-public-v1.json').read_text())
