   Inspect-Object $o[$k] "$loc/$k"
  }
 } elseif ($o -is [array]) { for ($i=0; $i -lt $o.Count; $i++) { Inspect-Object $o[$i] "$loc/$i" } }
}
Inspect-Object $p '"''
